43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_DIVISOR = 10; // 10 %, as an exact fraction
45	
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	};
50	
51	export const runScenario = (scenario: Scenario): ScenarioResult => {
52	  const quote = scenario.steps[0] as QuoteStep;
53	  const basePremium = quote.items.reduce(
54	    (sum, item) => sum + BASE_PREMIUMS[item.type],
55	    0,
56	  );
57	  const firstInsuranceSurcharge =
58	    basePremium / FIRST_INSURANCE_SURCHARGE_DIVISOR;
59	  const premium = basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
60	  return { results: [{ premium: Math.ceil(premium) }] };
61	};
