node -e '
const pct=(a,r)=>(a*r)/100;
const bad=(a,r)=>a*(r/100);
// rates the spec names: 10% first-insurance, 50% curse, 30% high-ench, 20% loyalty, 15% follow-up
const rates=[10,50,30,20,15,25];
let issues=0;
for(let a=0;a<=4000;a+=0.5){
  for(const r of rates){
    const good=pct(a,r), old=a/10;
    if(r===10 && good!==old){ console.log("DIVERGE from /10:",a,good,old); issues++; }
    if(!Number.isFinite(good)){ console.log("nonfinite",a,r); issues++; }
  }
}
console.log("divergences from previous /10 behaviour:",issues);
// show where the naive float form would have drifted
console.log("naive 197.5*... sample:", pct(1975,10), bad(1975,10), pct(1975,10)===bad(1975,10));
console.log("cursed sword 100 @50%:", pct(100,50), " sword 60 @10%:", pct(60,10));
'
